import type {
  MonthlyDocument,
  MonthlyDocumentCategory,
  ReceiptVisibility,
} from '../types/condo';

export const MONTHLY_DOC_CATEGORY_LABELS: Record<MonthlyDocumentCategory, string> = {
  extrato_bancario: 'Extrato Bancário',
  comprovante_pagamento: 'Comprovante de Pagamento',
  boleto_guia: 'Boleto / Guia DARF',
  nota_fiscal: 'Nota Fiscal (PDF / XML)',
  contrato: 'Contrato',
  recibo: 'Recibo / Cupom',
  encargos_fiscais: 'Encargos Trabalhistas (Terceirizada)',
  vistoria_midia: 'Vistoria / Foto / Vídeo',
};

function inferMimeType(diskFile: string, explicitMime?: string): string {
  if (explicitMime) return explicitMime;
  const lower = diskFile.toLowerCase();
  if (lower.endsWith('.pdf')) return 'application/pdf';
  if (lower.endsWith('.xml')) return 'application/xml';
  if (lower.endsWith('.png')) return 'image/png';
  if (lower.endsWith('.jpg') || lower.endsWith('.jpeg') || lower.endsWith('.jfif')) {
    return 'image/jpeg';
  }
  if (lower.endsWith('.mp4')) return 'video/mp4';
  return 'application/pdf';
}

function docEntry(
  id: string,
  competence: string,
  category: MonthlyDocumentCategory,
  title: string,
  diskFile: string,
  options?: {
    documentDate?: string;
    downloadName?: string;
    mimeType?: string;
    visibility?: ReceiptVisibility;
    notes?: string;
  }
): MonthlyDocument {
  return {
    id,
    competence,
    documentDate: options?.documentDate ?? null,
    title,
    category,
    fileName: options?.downloadName ?? diskFile,
    mimeType: inferMimeType(diskFile, options?.mimeType),
    storageMode: 'official_archive',
    dataUrl: null,
    externalUrl: `/assets/aistudio/${diskFile}`,
    visibility: options?.visibility ?? 'published_residents',
    notes: options?.notes ?? '',
    createdBy: 'archive_oficial',
  };
}

